with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('male sig', 'phrase', '01225c15-368f-55ae-b4a0-3287cfaac9af', 1, 'verb', null, 'наносити макіяж', 'Hun maler sig altid før morgenmaden.', 'Вона завжди наносить макіяж перед сніданком.'), ('sprede sig', 'phrase', '130303f1-2deb-575e-922b-7143ed8883ae', 1, 'verb', null, 'поширюватися', 'Nyheden spredte sig hurtigt i byen.', 'Новина швидко поширилася містом.'), ('røre rundt', 'phrase', '43a7447f-f02f-5fc8-b13d-911af7491811', 1, 'verb', null, 'перемішувати', 'Hun rører rundt i gryden med en ske.', 'Вона помішує в каструлі ложкою.'), ('ryste på hovedet', 'phrase', 'ef7769d8-034f-55fb-aa11-067a2f9b16d6', 1, 'verb', null, 'хитати головою (заперечно)', 'Hun rystede på hovedet, da jeg spurgte hende.', 'Вона похитала головою, коли я запитав.'), ('koncentrere sig om', 'phrase', '4b473d0d-f2d2-577d-ba33-95aede25b587', 1, 'verb', null, 'зосередитися на', 'Jeg koncentrerer mig om at læse bogen.', 'Я зосереджуюся на читанні книги.'), ('skille sig af med', 'phrase', '8f992a43-4cfc-55f4-9542-bb8b166389e9', 1, 'verb', null, 'позбуватися (чогось)', 'Hun vil gerne skille sig af med sin gamle sofa.', 'Вона хоче позбутися свого старого дивана.'), ('støde på', 'phrase', '9cee315a-3920-5b88-a253-59c941f74c47', 1, 'verb', null, 'натрапити (на щось)', 'Jeg stødte på en gammel ven i byen.', 'Я зустрів старого друга в місті.'), ('tilbringe tid', 'phrase', '5179801c-287b-5ad9-8d7b-dfb6a383456c', 1, 'verb', null, 'проводити час', 'Vi tilbringer tid sammen hver weekend.', 'Ми проводимо час разом щовихідних.'), ('klæde sig af', 'phrase', 'db62190c-5de6-5c43-a101-b09ac137901c', 1, 'verb', null, 'роздягатися', 'Børnene klædte sig af og hoppede i poolen.', 'Діти роздяглися і стрибнули у басейн.'), ('græde over', 'phrase', 'c61c9a54-e105-5b32-bfb4-09181cbeaf69', 1, 'verb', null, 'оплакувати (щось)', 'Hun græd over sin ødelagte telefon hele aftenen.', 'Вона плакала через зламаний телефон увесь вечір.'), ('brække sig', 'phrase', '61298f4a-d0d8-5a0a-9cba-2861eacc1ee1', 1, 'verb', null, 'блювати, рвати', 'Han spiste for meget og måtte brække sig bagefter.', 'Він з''їв забагато і після цього його знудило.'), ('føre dagbog', 'phrase', 'd259f90f-3b4f-5888-aaea-8b738727abac', 1, 'verb', null, 'вести щоденник', 'Hun fører dagbog hver aften.', 'Вона веде щоденник щовечора.'), ('køle af', 'phrase', 'e6b0fef5-7ccc-5873-ac8b-563a2cee2353', 1, 'verb', null, 'остигати (ставати холоднішим)', 'Suppen skal køle af før vi spiser.', 'Суп має охолонути перед їжею.'), ('køle af', 'phrase', '57e3e8f1-31a1-5374-8e80-45f10fc460eb', 2, 'verb', null, 'остигати (заспокоюватися)', 'Han må køle af inden vi taler om det.', 'Йому потрібно заспокоїтися, перш ніж ми про це говоримо.'), ('sværge på', 'phrase', 'dfaf898e-94a1-5d25-a328-e844c24c4c76', 1, 'verb', null, 'присягатися в чомусь', 'Han svor på at han talte sandt.', 'Він клявся, що говорить правду.'), ('gud og hvermand', 'phrase', 'ee3af7be-e97e-5e6f-9dea-0ab3cb4532ae', 1, 'phrase', null, 'всі і кожен (люди)', 'Gud og hvermand ved, at det er sandt.', 'Всі і кожен знають, що це правда.'), ('komme sig over', 'phrase', '053d28bb-05d1-5f1f-b49c-73aeb750b3ad', 1, 'verb', null, 'оговтатися (після хвороби, потрясіння)', 'Hun har lige kommet sig over en slem forkølelse.', 'Вона щойно одужала після сильної застуди.'), ('komme op at', 'phrase', 'a6c828f5-9d65-5840-b2a4-faaa30d8fc0d', 1, 'verb', null, 'посваритися (з кимось)', 'De kom op at skændes om penge.', 'Вони посварилися через гроші.'), ('have tid til', 'phrase', '79f10fcc-f98e-5b79-b40b-7710cfafd1f6', 1, 'verb', null, 'мати час на (щось)', 'Jeg har tid til en kop kaffe inden mødet.', 'У мене є час на каву перед зустріччю.'), ('tage tid', 'phrase', '1e1c1a45-4217-53ff-b808-4fec2befa744', 1, 'verb', null, 'займати час', 'Det tager tid at lære dansk.', 'Щоб вивчити данську, потрібен час.'), ('gå ind på', 'phrase', 'ba934f36-ce11-5305-ac9e-e5dc45f48693', 1, 'verb', null, 'погоджуватися (на пропозицію, план)', 'Hun gik ind på at hjælpe os i weekenden.', 'Вона погодилася допомогти нам на вихідних.'), ('finde sammen', 'phrase', 'fcdbda2a-3c0e-5e47-ba82-b67c1929efec', 1, 'verb', null, 'сходитися (починати стосунки)', 'De fandt sammen efter mange år som venner.', 'Вони почали зустрічатися після багатьох років дружби.'), ('stå sammen', 'phrase', '9bb0cbe0-780d-59f0-a093-d5ef95ddd287', 1, 'verb', null, 'триматися разом (підтримувати одне одного)', 'Vi står sammen, når det er svært.', 'Ми тримаємося разом, коли важко.'), ('det er lige meget', 'phrase', 'f802c411-438f-5df0-b3c9-3077a076ef5f', 1, 'phrase', null, 'неважливо', 'Det er lige meget, hvad vi spiser i aften.', 'Неважливо, що ми їмо сьогодні ввечері.'), ('sætte sig for', 'phrase', '3aa0e9ba-35dd-5d8c-8929-eaf5d525ef5f', 1, 'verb', null, 'вирішити (твердо наміритися)', 'Hun satte sig for at lære dansk på et år.', 'Вона вирішила вивчити данську за один рік.'), ('sætte sig for at', 'phrase', 'b75c3f0b-1c03-5813-9370-1650db725d7b', 1, 'verb', null, 'вирішити (щось зробити)', 'Hun satte sig for at lære dansk på et år.', 'Вона вирішила вивчити данську за один рік.'), ('tale sammen', 'phrase', '5af2ef4c-e9c6-5e72-84ca-65b58f196ad0', 1, 'verb', null, 'розмовляти (один з одним)', 'Vi taler sammen hver aften.', 'Ми розмовляємо щовечора.'), ('egne sig', 'phrase', 'ac461631-26e7-599c-ab30-0083f5dffca5', 1, 'verb', null, 'підходити, годитися', 'Den her bog egner sig godt til begyndere.', 'Ця книга чудово підходить для початківців.'), ('finde vej', 'phrase', '1051440f-1be6-5383-a295-0ca7038eb9c0', 1, 'verb', null, 'знаходити дорогу', 'Hun fandt vej til stationen uden kort.', 'Вона знайшла дорогу до станції без карти.'), ('bruge penge på', 'phrase', 'f310029d-0bcb-552f-8ca6-c3f08b709601', 1, 'verb', null, 'витрачати гроші на', 'Jeg bruger penge på mad hver dag.', 'Я щодня витрачаю гроші на їжу.'), ('lægge ud', 'phrase', '5f44c8ca-79f7-5614-879d-8ce08b635fef', 1, 'verb', null, 'починати (розповідь, пояснення)', 'Hun lagde ud med at fortælle om sin ferie.', 'Вона почала з розповіді про свою відпустку.'), ('lægge ud', 'phrase', '2c46f8f8-5d0c-5e08-8088-43c7b1396c14', 2, 'verb', null, 'платити за інших (з подальшим поверненням)', 'Jeg lagde ud for billetterne til koncerten.', 'Я поки що заплатив за квитки на концерт за всіх.'), ('høre op med at', 'phrase', '0c6ac8db-bddb-5f96-8086-8fc99f0ea561', 1, 'verb', null, 'переставати (робити щось)', 'Jeg hører op med at ryge i morgen.', 'Завтра кину курити.'), ('slå på', 'phrase', '70343dec-3859-5823-b3c6-d0339c4479d9', 1, 'verb', null, 'вдаряти (по чомусь)', 'Han slog på bordet med knytnæven.', 'Він вдарив кулаком по столу.'), ('slå på', 'phrase', '3361d615-150b-5680-9f9f-03fad3a1a6c8', 2, 'verb', null, 'підкреслювати (у мовленні)', 'Hun slår på, at det er vigtigt at møde til tiden.', 'Вона наголошує, що важливо приходити вчасно.'), ('tænke efter', 'phrase', '4ba2c422-ff92-53d0-921f-0bb3f41b8333', 1, 'verb', null, 'обмірковувати, поміркувати', 'Du skal tænke efter før du svarer.', 'Треба подумати, перш ніж відповідати.'), ('synes om', 'phrase', '9c384956-cff2-5b2e-b7c2-8fa566546530', 1, 'verb', null, 'подобатися (мати думку)', 'Jeg synes om den nye lærer.', 'Мені подобається новий вчитель.'), ('gå rundt om', 'phrase', 'bc16c256-2a57-53c5-bd03-d79f1dcb107c', 1, 'verb', null, 'обходити (навколо)', 'Vi gik rundt om søen i aftes.', 'Вчора ввечері ми обійшли навколо озера.'), ('leve for', 'phrase', 'de8fde62-6d44-5755-af36-fbb122645ecf', 1, 'verb', null, 'жити заради', 'Hun lever for sin musik.', 'Вона живе заради своєї музики.'), ('leve videre', 'phrase', 'a7e981a6-78b3-5607-b742-ca3dd9cdfb78', 1, 'verb', null, 'продовжувати жити', 'Efter ulykken prøvede han bare at leve videre.', 'Після аварії він просто намагався жити далі.'), ('sætte ord på', 'phrase', 'd2530c1c-3d19-5a8d-a17e-4620203b529d', 1, 'verb', null, 'висловлювати словами', 'Hun sætter ord på sine følelser.', 'Вона висловлює свої почуття словами.'), ('stå stille', 'phrase', '74d0397f-32d5-5002-9d8d-efe717fa978d', 1, 'verb', null, 'стояти на місці (не рухатися)', 'Bilen stod stille i lang tid.', 'Автомобіль довго стояв на місці.'), ('stå stille', 'phrase', '5704ad0e-fee7-50de-8e95-ee2a0f3e4b03', 2, 'verb', null, 'зупинятися (про процес)', 'Arbejdet står stille på grund af regnen.', 'Робота стоїть через дощ.'), ('trække sig tilbage', 'phrase', 'efe681e3-ad3f-54db-bc6d-509c3ebf156f', 1, 'verb', null, 'відступати (фізично)', 'Soldaterne fik besked på at trække sig tilbage fra området.', 'Солдатам наказали відступити з району.'), ('trække ud', 'phrase', '4cc3bb01-1d1f-552c-a3fd-64f50103a000', 1, 'verb', null, 'затягуватися (про час)', 'Mødet trak ud og varede over to timer.', 'Зустріч затягнулася і тривала понад дві години.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0008' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
